fn branch(x: i32, y: i32, ang: i32, len: i32, depth: i32, t: i32) {
    if depth == 0 { return; }
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let ai: i32 = ang & 31;
    let ex: i32 = x + tab[ai] * len / 127;
    let ey: i32 = y - tab[(ai + 8) & 31] * len / 127;
    let c: i32 = if depth > 4 { 0x8b5a2b } else { 0x33cc55 };
    host::display::draw_line(x, y, ex, ey, c);
    if depth > 4 {
        host::display::draw_line(x + 1, y, ex + 1, ey, c);
    }
    let sway: i32 = tab[(t / 2 + depth * 5) & 31] / 100;
    branch(ex, ey, ang - 4 + sway, len * 2 / 3, depth - 1, t);
    branch(ex, ey, ang + 4 + sway, len * 2 / 3, depth - 1, t);
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x0a1006);
    host::display::fill_rect(0, h - 16, w, 16, 0x1c140a);
    branch(w / 2, h - 16, 0, 110, 7, t);
    host::display::present();
}
